"""Parcel records."""


class Parcel:
    def __init__(self, depot, grams):
        self.depot = depot
        self.grams = grams

    def __repr__(self):
        return "Parcel(%r, %r)" % (self.depot, self.grams)


ROWS = [('leeds', 55), ('york', 20), ('hull', 31), ('bath', 45), ('leeds', 40), ('leeds', 13), ('york', 24)]


def load_parcels():
    """Yield the stored parcels one at a time."""
    for depot, grams in ROWS:
        yield Parcel(depot, grams)

