"""A ledger of parcels."""


class ParcelLedger:
    def __init__(self, parcels=()):
        self._parcels = list(parcels)

    def parcels(self):
        """Return the parcels held (a copy, so callers cannot change the ledger)."""
        return list(self._parcels)

    def add(self, parcel):
        """Add one parcel to the ledger."""
        self.parcels().append(parcel)

    def total(self):
        """Return the total grams of the parcels held."""
        return sum(x.grams for x in self._parcels)


def largest_grams(parcels):
    """Return the largest grams, or None when there are no parcels."""
    values = [x.grams for x in parcels]
    return max(values) if values else None


def depot_names(parcels):
    """Return the distinct depot values, in first-seen order."""
    names = []
    for x in parcels:
        if x.depot not in names:
            names.append(x.depot)
    return names

